function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 100000) return 'nums needs 2 to 100000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 1000000)) return 'Each value is an integer from 0 to 1000000.';
  let low = Infinity;
  const suffix = new Array(nums.length);
  for (let i = nums.length - 1; i >= 0; i--) { low = Math.min(low, nums[i]); suffix[i] = low; }
  let high = -Infinity;
  for (let i = 0; i + 1 < nums.length; i++) { high = Math.max(high, nums[i]); if (high <= suffix[i + 1]) return null; }
  return 'nums must allow at least one valid cut.';
}

