  const n = nums.length;
  const suffixMin = new Array(n);
  suffixMin[n - 1] = nums[n - 1];
  for (let i = n - 2; i >= 0; i--) {
    suffixMin[i] = Math.min(nums[i], suffixMin[i + 1]);
  }

  let prefixMax = nums[0];
  for (let i = 1; i < n; i++) {
    if (prefixMax <= suffixMin[i]) {
      return i;
    }
    prefixMax = Math.max(prefixMax, nums[i]);
  }
  return -1;
}

