function generate(rand, size) {
  const n = size === 'large' ? 2000 : 2 + Math.floor(rand() * 7);
  const top = size === 'large' ? 1000000 : 1 + Math.floor(rand() * 6);
  // Build a guaranteed cut: values before it are at most pivot, values after it are at least pivot.
  const cut = 1 + Math.floor(rand() * (n - 1));
  const pivot = Math.floor(rand() * (top + 1));
  const nums = [];
  for (let i = 0; i < n; i++) {
    if (i < cut) nums.push(Math.floor(rand() * (pivot + 1)));
    else nums.push(pivot + Math.floor(rand() * (top - pivot + 1)));
  }
  return [nums];
}
